Sender() {
    do {
        wait(empty);
        wait(mutex);
        发邮件;
        signal(mutex);
        signal(full);
    } while (TRUE);
}

Reader() {
    do {
        wait(full);
        wait(mutex);
        读邮件并自动删除;
        signal(mutex);
        signal(empty);
    } while (TRUE);
}
